package cn.mop.api;
import cn.mop.domain.*;
import cn.mop.domain.monitoring.EventNoiseTrendReader;
import cn.mop.domain.monitoring.EventNoiseTrendReader.*;
import cn.mop.domain.monitoring.MonitoringEventPipeline.NoiseLayer;
import jakarta.servlet.http.HttpServletRequest;
import org.springframework.context.annotation.Profile;
import org.springframework.web.bind.annotation.*;
import java.util.*;
@RestController @Profile("remote_test") @RequestMapping("/api/v1/metrics/event-noise-trend")
public final class EventNoiseTrendController {
 private final PlatformRepository platform;private final EventNoiseTrendReader reader;
 public EventNoiseTrendController(PlatformRepository platform,EventNoiseTrendReader reader){this.platform=platform;this.reader=reader;}
 @GetMapping Object read(HttpServletRequest r){var m=member(r);if(!Set.of("window").containsAll(r.getParameterMap().keySet())||r.getParameterMap().values().stream().anyMatch(v->v==null||v.length!=1||v[0]==null||v[0].length()>16))throw invalid();Window window;try{window=Window.valueOf(Optional.ofNullable(r.getParameter("window")).orElse("HOURS_24"));}catch(Exception bad){throw invalid();}var access=new Access(UUID.fromString(m.tenantId()),UUID.fromString(m.userId()),m.permissionVersion());var result=reader.read(access,window);if(result==null||!result.access().equals(access)||result.window()!=window)throw new DomainException(503,"EVENT_NOISE_TREND_UNAVAILABLE","趋势来源与当前授权不符");var data=dto(result);DashboardReadAuthorization.recheck(r,platform,m);return ApiResponse.success(data,r);}
 static Map<String,Object> dto(Snapshot s){return ApiResponse.map("tenant_id",s.access().tenantId().toString(),"actor_id",s.access().actorId().toString(),"permission_version",s.access().permissionVersion(),"observed_at",s.observedAt().toString(),"timezone","Asia/Shanghai","window",s.window().name(),"bucket_seconds",s.window().seconds,"metric_version",EventNoiseTrendReader.VERSION,"period",ApiResponse.map("from",s.buckets().get(0).from().toString(),"to",s.observedAt().toString()),"buckets",s.buckets().stream().map(b->ApiResponse.map("from",b.from().toString(),"to",b.to().toString(),"raw_count",b.rawCount(),"after_fingerprint_merge_count",b.afterFingerprintMergeCount(),"layers",layers(b.layers()))).toList(),"totals",layers(s.totals()),"markers",s.markers().stream().map(m->ApiResponse.map("record_id",m.recordId().toString(),"event_id",m.eventId().toString(),"rule_name",m.ruleName(),"severity",m.severity(),"recorded_at",m.recordedAt().toString())).toList(),"markers_truncated",s.markersTruncated(),"marker_limit",8,"event_metadata_basis","CURRENT_EVENT_PROJECTION","final_notification_count",null,"noise_reduction_percent",null,"noise_reduction_status","FINAL_NOTIFICATION_SOURCE_UNAVAILABLE","timestamp_basis","NOISE_LEDGER_RECORDED_AT","source","CURRENT_AUTHORIZED_NOISE_LEDGER","collection_freshness_verified",false,"final_notifications_verified",false,"writes_performed",false);}
 @GetMapping("/records") Object records(HttpServletRequest r){var m=member(r);var params=r.getParameterMap();if(!Set.of("from","to","before","before_id","page_size").containsAll(params.keySet())||!params.containsKey("from")||!params.containsKey("to")||params.containsKey("before")!=params.containsKey("before_id")||params.values().stream().anyMatch(v->v==null||v.length!=1||v[0]==null||v[0].length()>64))throw invalid();java.time.Instant from,to;RecordCursor before=null;int size=20;try{from=java.time.Instant.parse(r.getParameter("from"));to=java.time.Instant.parse(r.getParameter("to"));if(params.containsKey("before")){if(!uuid(r.getParameter("before_id")))throw invalid();before=new RecordCursor(java.time.Instant.parse(r.getParameter("before")),UUID.fromString(r.getParameter("before_id")));}if(params.containsKey("page_size"))size=Integer.parseInt(r.getParameter("page_size"));if(size<1||size>50)throw invalid();}catch(Exception bad){throw invalid();}if(!from.isBefore(to)||from.getNano()%1000000!=0||to.getNano()%1000000!=0||java.time.Duration.between(from,to).compareTo(java.time.Duration.ofDays(1))>0||before!=null&&(before.recordedAt().isBefore(from)||!before.recordedAt().isBefore(to)))throw invalid();var access=new Access(UUID.fromString(m.tenantId()),UUID.fromString(m.userId()),m.permissionVersion());var page=reader.records(access,from,to,before,size);if(page==null||!page.access().equals(access)||!page.from().equals(from)||!page.to().equals(to)||page.pageSize()!=size)throw new DomainException(503,"EVENT_NOISE_TREND_UNAVAILABLE","原始记录明细与当前范围不符");if(before==null&&(page.items().size()!=Math.min(page.totalCount(),size)||(page.next()!=null)!=(page.totalCount()>size)))throw new DomainException(503,"EVENT_NOISE_TREND_UNAVAILABLE","原始记录首页计数不完整");if(before!=null&&!page.items().isEmpty()){var first=page.items().get(0);if(first.recordedAt().isAfter(before.recordedAt())||first.recordedAt().equals(before.recordedAt())&&first.id().toString().compareTo(before.id().toString())>=0)throw new DomainException(503,"EVENT_NOISE_TREND_UNAVAILABLE","原始记录越过原游标");}var data=recordDto(page);DashboardReadAuthorization.recheck(r,platform,m);return ApiResponse.success(data,r);}
 static Map<String,Object> recordDto(RecordPage p){return ApiResponse.map("tenant_id",p.access().tenantId().toString(),"actor_id",p.access().actorId().toString(),"permission_version",p.access().permissionVersion(),"from",p.from().toString(),"to",p.to().toString(),"observed_at",p.observedAt().toString(),"page_size",p.pageSize(),"total_count",p.totalCount(),"items",p.items().stream().map(r->ApiResponse.map("record_id",r.id().toString(),"event_id",r.eventId().toString(),"recorded_at",r.recordedAt().toString(),"detail",r.detail())).toList(),"next",p.next()==null?null:ApiResponse.map("before",p.next().recordedAt().toString(),"before_id",p.next().id().toString()),"layer","RAW_INTAKE","timestamp_basis","NOISE_LEDGER_RECORDED_AT","source","CURRENT_AUTHORIZED_NOISE_LEDGER","snapshot_scope","SINGLE_READ_PAGE_NOT_GLOBAL_SNAPSHOT","writes_performed",false);}
 private static Map<String,Object> layers(Map<NoiseLayer,Long> values){var result=new LinkedHashMap<String,Object>();for(var layer:NoiseLayer.values())result.put(layer.name(),values.get(layer));return result;}
 private Membership member(HttpServletRequest r){if(r.getUserPrincipal()==null||r.getSession(false)==null||!(r.getSession(false).getAttribute("mop.tenant_id") instanceof String tenant))throw expired();String actor=r.getUserPrincipal().getName();if(!uuid(actor)||!uuid(tenant))throw expired();var m=platform.membership(actor,tenant).orElseThrow(EventNoiseTrendController::expired);if(!m.active()||!m.userId().equals(actor)||!m.tenantId().equals(tenant)||m.permissionVersion()<1||m.permissionVersion()>EventNoiseTrendReader.MAX)throw expired();if(!Capabilities.internal(m.role())||!m.capabilities().containsAll(List.of("dashboard:read","tickets:read")))throw new DomainException(403,"ACTION_FORBIDDEN","当前成员不能读取内部降噪趋势");return m;}
 private static boolean uuid(String s){return s!=null&&s.matches("[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}");}
 private static DomainException invalid(){return new DomainException(400,"VALIDATION_ERROR","趋势仅接受明确时间预设，不接受身份或来源覆盖");}
 private static DomainException expired(){return new DomainException(401,"SESSION_EXPIRED","当前事件趋势会话或权限已失效");}
}
